package io.wegoh.app.nativeauth

import android.test.InstrumentationTestCase
import org.json.JSONObject
import java.security.KeyStore
import java.security.Signature
import android.util.Base64

/** Synthetic, isolated vectors generated by the authoritative Python codec. */
class NativeAccessCodecTest : InstrumentationTestCase() {
    fun testRevokeOnlyFixedVectorAndCommitment() {
        val cap=NativeAccessCodec.preExchangeRevoke("v".repeat(43),"a".repeat(64),"b".repeat(32))
        assertEquals("odVhwXd0ypx3ma_0UQ30GGbsemFmhSBXff4g8vEon7U",cap)
        assertEquals("c87a5ddb69cbf1d9d920dd6a2ea159bbe02af312002e716c3d0c0bc5b2db93d3",NativeAccessCodec.revokeCommitment(cap))
    }

    fun testSharedWireCanonicalProofAndCapabilities() {
        val app=instrumentation.targetContext
        val vector=JSONObject(instrumentation.context.assets.open("native_access_vectors.json").bufferedReader().use { it.readText() })
        assertTrue(vector.getBoolean("syntheticOnly"))
        assertEquals(vector.getString("wireSha256"),NativeDeviceIdentity.sha256(app.assets.open("native_access_wire.json").use { boundedBytes(it,NATIVE_WIRE_MAX_BYTES) }))
        val codec=NativeAccessCodec(app)
        val request=vector.getJSONObject("request")
        codec.request("CONNECTION_CLAIM",request)
        assertEquals(vector.getString("canonical"),String(NativeAccessCodec.canonical(request),Charsets.UTF_8))
        val transcript=codec.transcript("CONNECTION_CLAIM",request,vector.getString("installationKeyId"),vector.getString("challenge"),vector.getString("connectionId"))
        assertEquals(vector.getString("transcript"),String(transcript,Charsets.US_ASCII))
        for(purpose in listOf("recovery","revoke")) assertEquals(vector.getString(purpose+"Capability"),
            NativeAccessCodec.capability(request.getString("codeVerifier"),vector.getString("grantId"),purpose))
        val id=java.util.UUID.randomUUID().toString().replace("-","")
        val identity=NativeDeviceIdentity(app,id);identity.initialize()
        val signature=Base64.decode(identity.signAccess(transcript),Base64.URL_SAFE or Base64.NO_PADDING or Base64.NO_WRAP)
        val store=KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        assertTrue(Signature.getInstance("SHA256withRSA").run { initVerify(store.getCertificate("wegoh.native.$id").publicKey);update(transcript);verify(signature) })
        // Only this test's newly created synthetic key; never the product/profile key.
        store.deleteEntry("wegoh.native.$id")
    }
    fun testStrictJsonAndTypedFailures() {
        val codec=NativeAccessCodec(instrumentation.targetContext)
        val invalid=listOf("{\"a\":1,\"a\":2}","{\"n\":true,\"n\":false}","{\"n\":NaN}","{\"n\":1.0}","{\"n\":01}","{\"n\":null}","{\"n\":9223372036854775808}","{\"n\":\"\\ud800\"}","{} trailing")
        for(raw in invalid) assertRejected { StrictNativeJson.parse(raw.toByteArray()) }
        val vector=JSONObject(instrumentation.context.assets.open("native_access_vectors.json").bufferedReader().use { it.readText() })
        for(value in listOf<Any>(true,"1",1.0,2)) assertRejected {
            codec.request("CONNECTION_CLAIM",JSONObject(vector.getJSONObject("request").toString()).put("authorizationVersion",value))
        }
        assertRejected { codec.request("CONNECTION_CLAIM",JSONObject(vector.getJSONObject("request").toString()).put("extra",true)) }
        assertRejected { codec.request("CONNECTION_CLAIM",JSONObject(vector.getJSONObject("request").toString()).put("proofNonce","A".repeat(42)+"B")) }
        val mixed=JSONObject().put("z","한글 😀 /\n").put("a",true).put("n",2L)
        assertEquals("{\"a\":true,\"n\":2,\"z\":\"한글 😀 /\\n\"}",String(NativeAccessCodec.canonical(mixed),Charsets.UTF_8))
    }
    fun testSha2IssuerSignaturesAreIndependentFromRsaInstallationKey() {
        val root=JSONObject(instrumentation.context.assets.open("native_access_certificate_vectors.json").bufferedReader().use { it.readText() })
        assertTrue(root.getBoolean("syntheticOnly"));val codec=NativeAccessCodec(instrumentation.targetContext)
        val rows=root.getJSONArray("rows")
        for(i in 0 until rows.length()) {
            val row=rows.getJSONObject(i)
            codec.response("CERTIFICATE_RECOVER",200,row.getJSONObject("response"),"a".repeat(32),row.getString("installationKeyId"))
        }
    }
    fun testOptionalKeyUsageStillRejectsExplicitNonSigningOrCaPurposes() {
        val root=JSONObject(instrumentation.context.assets.open("native_access_certificate_vectors.json").bufferedReader().use { it.readText() })
        val codec=NativeAccessCodec(instrumentation.targetContext)
        val rows=root.getJSONArray("keyUsageCases")
        assertEquals(4,rows.length())
        for(i in 0 until rows.length()) {
            val row=rows.getJSONObject(i);val response=row.getJSONObject("response")
            val leaf=NativeDeviceIdentity.parseCertificates(response.getJSONObject("certificateReceipt").getString("certificatePem")).single()
            if(row.getBoolean("accepted")) {
                assertNull(leaf.keyUsage)
                NativeDeviceIdentity.requireClientKeyUsage(leaf)
                codec.response("CERTIFICATE_RECOVER",200,response,"a".repeat(32),row.getString("installationKeyId"))
            } else {
                assertNotNull(leaf.keyUsage)
                assertRejected { NativeDeviceIdentity.requireClientKeyUsage(leaf) }
                assertRejected { codec.response("CERTIFICATE_RECOVER",200,response,"a".repeat(32),row.getString("installationKeyId")) }
            }
        }
    }
    fun testNeutralBoundaryErrorIdentifiers() {
        val codec=NativeAccessCodec(instrumentation.targetContext)
        fun expect(code: String, block: () -> Unit) {
            try { block();fail("Expected boundary rejection") }
            catch(expected: IllegalStateException) { assertEquals(code,expected.message) }
        }
        expect("NATIVE_RESPONSE_INVALID") {
            codec.response("CONNECTION_BEGIN",200,JSONObject(),"a".repeat(32),"b".repeat(64))
        }
        expect("NATIVE_WIRE_INVALID") { codec.operation("UNKNOWN_ACTION") }
        for(raw in listOf("[]","{\"value\":\"\\q\"}","{\"value\":\"unfinished")) {
            expect("NATIVE_JSON_INVALID") { StrictNativeJson.parse(raw.toByteArray()) }
        }
    }
    private fun assertRejected(block: () -> Unit) {
        try { block();fail("Expected strict rejection") } catch(expected: Exception) { }
    }
}
